class ViewMore extends HTMLElement{constructor(){super(),this.container=document.querySelector(""+this.dataset.targetWrapper),this.url=this.getAttribute("data-next-page-url"),this.init()}init(){this.container&&this.url&&this.addEventListener("click",t=>{this.getData(this,t)})}getData(){fetch(this.url).then(t=>t.text()).then(t=>{t=(new DOMParser).parseFromString(t,"text/html");this.addProducts(t),this.changeUrl(t)})}addProducts(t){t=t.querySelectorAll(".collection__content-grid-list-item");Array.from(t).forEach(t=>{this.container.append(t)})}changeUrl(t){t=t.querySelector("[data-next-page-url]")||null;if(this.url=t?t.getAttribute("data-next-page-url"):null,!this.url)return this.setAttribute("aria-hidden","true"),!1;this.setAttribute("data-next-page-url",this.url)}}customElements.define("view-more",ViewMore);